function apply(operator, left, right) {
…
  switch (value) {
…
    case '**': return left ** right;
    case '//': {
      const quotient = Math.trunc(left / right);
      return quotient === 0 ? 0 : quotient;
    }
    case '%': {
      const remainder = left % right;
      if (remainder === 0) return 0;
      return remainder;
    }
    case '<': return left < right;
    case '<=': return left <= right;
    case '>': return left > right;
    case '>=': return left >= right;
    case '==': return left === right;
    case '!=': return left !== right;
    default: throw new Error('Invalid AST operator');
  }
}

/** Evaluate with explicit frames, so a long left-deep binary tree is safe. */
function evaluateAst(root, variables) {
  const frames = [{ node: root, phase: 0 }];
  let result;
  while (frames.length) {
    const frame = frames[frames.length - 1];
    const node = frame.node;
    if (node.type === 'number') {
      result = node.value;
      frames.pop();
    } else if (node.type === 'variable') {
      if (!Object.prototype.hasOwnProperty.call(variables, node.name)) {
        throw new ExprError('Unknown variable', node.column);
      }
      result = variables[node.name];
      frames.pop();
    } else if (node.type === 'unary') {
      if (frame.phase === 0) {
        frame.phase = 1;
        frames.push({ node: node.operand, phase: 0 });
      } else {
        result = node.operator.value === '-' ? -Number(result) : Number(result);
        frames.pop();
      }
    } else if (node.type === 'binary') {
      if (frame.phase === 0) {
        frame.phase = 1;
        frames.push({ node: node.left, phase: 0 });
      } else if (frame.phase === 1) {
        frame.left = result;
        frame.phase = 2;
        frames.push({ node: node.right, phase: 0 });
      } else {
        result = apply(node.operator, frame.left, result);
        frames.pop();
      }
    } else if (node.type === 'comparison') {
      if (frame.phase === 0) {
        frame.phase = 1;
        frames.push({ node: node.operands[0], phase: 0 });
      } else if (frame.phase === 1) {
        frame.left = result;
        frame.index = 0;
        frame.phase = 2;
        frames.push({ node: node.operands[1], phase: 0 });
      } else {
        const right = result;
        if (!apply(node.operators[frame.index], frame.left, right)) {
          result = false;
          frames.pop();
        } else if (frame.index + 1 === node.operators.length) {
          result = true;
          frames.pop();
        } else {
          frame.left = right;
          frame.index += 1;
          frames.push({ node: node.operands[frame.index + 1], phase: 0 });
        }
      }
    } else if (node.type === 'call') {
      if (frame.phase === 0) {
        frame.phase = 1;
        frame.index = 0;
        frames.push({ node: node.args[0], phase: 0 });
      } else {
        const value = Number(result);
        if (frame.index === 0) frame.value = value;
        else if (node.name === 'min') frame.value = Math.min(frame.value, value);
        else frame.value = Math.max(frame.value, value);
        frame.index += 1;
        if (frame.index === node.args.length) {
          result = node.name === 'abs' ? Math.abs(frame.value) : frame.value;
          frames.pop();
        } else {
          frames.push({ node: node.args[frame.index], phase: 0 });
        }
      }
    } else {
      throw new Error('Invalid AST node');
    }
  }
  return result;
}

content.thinking:
Now let's identify the bugs against the contract:

1. **Grammar mismatch**: Contract says:
   - `unary := ('+' | '-') unary | power`
   - `power := primary ('**' unary)?`

   Parser has `product := unary ...` where `unary` handles signs and `power` loops `**` left-associatively. Current parser: product → power; power := unary ('**' unary)* — this makes `**` left-associative (2 ** 3 ** 2 = (2**3)**2 = 64 instead of 512) and unary binds above power on the left... wait: power calls unary, unary handles signs then primary. So -2 ** 2 parses as unary(-) applied to... let's see: power → unary → unary sees '-', takes it, operand = unary → primary → 2. Then back in power, sees '**', right = unary → 2. So -2 ** 2 = (-2) ** 2 = 4, but contract says -4 (unary binds below ** on its left).

   Fix: implement per grammar:
   - product := unary (('*'|...) unary)*
   - unary := ('+'|'-') unary | power
   - power := primary ('**' unary)?

   So `power` calls `primary`, optional `**` then `unary` (right-assoc, right operand may have sign). And `unary` falls to `power` rather than `primary`.

2. **Comparison chaining**: Contract: comparisons chain: `a < b <= c` means `a < b and b <= c`, shared operands evaluated once, short-circuit remaining operands. Parser builds left-associative binary comparisons. Evaluator has a 'comparison' node type that parser never creates! Need parser to build a chained comparison node: `comparison := sum (op sum)*` producing `{type:'comparison', operators: [...], operands: [...]}` when there's at least one operator.

3. **Parenthesized comparison results used in arithmetic are numbers 0/1**: `(a < b) + 1` — booleans converted via Number() — apply() does `Number(left)`, so booleans become 0/1. That works. But the result of evaluate returning boolean for comparisons — that's per contract (produce booleans). In arithmetic, Number() coerces. Equality: `==` between number and boolean: contract says "numeric equality likewise treats these booleans as 0/1" — apply does Number() on both, so `(1 < 2) == 1` → Number(true)===1 → true. OK.

   But what about `==` in a chain without arithmetic? Chained comparison uses apply too with Number coercion. Fine.

