'use strict';
const assert = require('node:assert/strict');
const { evaluate, ExprError } = require('./src/index');

let n = 0;
const eq = (src, expected, vars) => { assert.equal(evaluate(src, vars), expected, src); n++; };
const throwsAt = (src, column) => {
  try { evaluate(src); } catch (e) {
    assert.ok(e instanceof ExprError, src + ' should raise ExprError');
    assert.equal(e.column, column, `${src} column`);
    n++; return;
  }
  assert.fail(src + ' should throw');
};

// Python arithmetic semantics
eq('-7 // 2', -4); eq('-7 % 3', 2); eq('7 % -3', -2); eq('7 // 2', 3);
eq('-7 // -2', 3); eq('7 // -2', -4); eq('-7 % -3', -1);
eq('0 // 5', 0); eq('0 % 5', 0); eq('1 - 7 // 2', 5);
assert.equal(Object.is(evaluate('0 // -5'), 0), true); // positive zero
assert.equal(Object.is(evaluate('0 % -5'), 0), true);
eq('7.5 % 2', 1.5); eq('-7.5 % 2', 0.5); eq('7 // 0.5', 14);
// integer invariant a == (a//b)*b + a%b
for (const [a, b] of [[-7, 2], [7, -3], [-7, -3], [100, 7]]) {
  eq(`(${a} // ${b}) * ${b} + (${a} % ${b})`, a);
}

// division by zero columns (operator token position)
throwsAt('1 / 0', 3);
throwsAt('1 // 0', 3);
throwsAt('1 % 0', 3);
throwsAt('  12 + 3 % 0', 10);
throwsAt('1 / -0', 3);

// power / unary precedence and associativity
eq('-2 ** 2', -4); eq('2 ** -1', 0.5); eq('2 ** 3 ** 2', 512);
eq('(-2) ** 2', 4); eq('2 ** +3', 8); eq('- 2 ** 2 ** 3', -256);
eq('2 ** -1 ** 2', 0.5); eq('3 * -2 ** 2', -12); eq('--5', 5);
eq('+-+5', -5);

// precedence
eq('1 + 2 * 3', 7); eq('10 - 4 - 3', 3); eq('100 / 10 / 2', 5);
eq('2 * 3 % 4', 2); eq('1 + 2 < 4', true); eq('1 + 2 * 3 == 7', true);

// comparisons: chaining, no intermediate boolean comparison
eq('1 < 2 <= 2', true); eq('3 > 2 > 1', true); eq('1 < 2 > 3', false);
eq('1 == 1 != 2', true); eq('5 == 5 == 5', true); // chained, NOT (5==5)==5 -> true==5 false
eq('1 == 1 == 1', true); // chained: 1==1 and 1==1
eq('(1 == 1) == 1', true); // parenthesized boolean is 1
eq('(2 == 1) + 5', 5);   // boolean arithmetic 0
eq('(1 < 2) + 5', 6);   // boolean arithmetic 1
eq('(1 < 2) * 10', 10);
eq('3 == 3.0', true); eq('1 != 2', true);

// short-circuit: shared operands evaluated once, rest skipped
{
  let reads = 0;
  const vars = {};
  Object.defineProperty(vars, 'x', { get: () => { reads++; return 5; }, enumerable: true });
  assert.equal(evaluate('x < x < x', vars), false); // 5<5 false on first
  assert.equal(reads, 2, 'short-circuit after false comparison');
  n++;
  reads = 0;
  assert.equal(evaluate('x < 6 < x', vars), false);
  assert.equal(reads, 2, 'x read once per occurrence');
  n++;
  reads = 0;
  assert.equal(evaluate('1 < x < x < x', vars), false); // x=5: 1<5 ok, 5<5 false
  assert.equal(reads, 2);
  n++;
}
// parse errors detected before evaluation: no variable reads on syntax error
{
  let reads = 0;
  const vars = {};
  Object.defineProperty(vars, 'y', { get: () => { reads++; return 1; }, enumerable: true });
  assert.throws(() => evaluate('y + foo(1)', vars), ExprError);
  assert.equal(reads, 0);
  n++;
  assert.throws(() => evaluate('y + abs(1, 2)', vars), ExprError);
  assert.equal(reads, 0);
  n++;
}

// functions
eq('min(3, 1, 2)', 1); eq('max(3, 1, 2)', 3); eq('abs(-4)', 4);
eq('min(5)', 5); eq('abs(2 - 9)', 7); eq('min(2*3, 1+1)', 2);
eq('max(min(1,2), 10)', 10);
throwsAt('foo(1)', 1);      // unknown function at identifier
throwsAt('  bar(1, 2)', 3);
throwsAt('min()', 1);       // wrong arg count
throwsAt('abs(1, 2)', 1);
throwsAt('min(1,)', 1);     // trailing comma: error somewhere (ExprError)
throwsAt('MAX(1, 2)', 1);   // case-sensitive

// variables
eq('a + b', 3, { a: 1, b: 2 });
eq('_x1 * 2', 6, { _x1: 3 });
throwsAt('c', 1);           // unknown variable at identifier
throwsAt('  1 + zz', 5);
eq('toString', 42, { toString: 42 }); // own property only
throwsAt('toString', 1);
// no mutation
{
  const vars = { a: 1 };
  evaluate('a + a', vars);
  assert.deepEqual(vars, { a: 1 });
  n++;
}

// numbers
eq('1.5e-3 * 1000', 1.5); eq('.5 + .5', 1); eq('5. - 2.', 3);
eq('1E2', 100); eq('2e+1', 20); eq('1_0', undefined) , // placeholder removed below

// whitespace & columns
eq('  1\t+\n 2 ', 3);
throwsAt('', 1);
throwsAt('   ', 4);         // unexpected end = length+1 incl trailing ws
throwsAt('1 +', 4);
throwsAt('1 + ', 5);
throwsAt('(1', 3);
throwsAt('1 2', 3);
throwsAt('1 @ 2', 3);       // invalid char at its column
throwsAt('  1 + @', 7);
throwsAt('1 & 2', 3);
throwsAt('1 ! 2', 3);
throwsAt(')', 1);
throwsAt('min(1 2)', 8);

console.log(`contract checks passed: ${n}`);

